#!/usr/bin/env bash
# init_flags.sh — generate a fresh runtime-only flag token. Writes a .env the
# compose stack reads. Run once before `docker compose up`. Re-run to rotate.
set -euo pipefail
cd "$(dirname "$0")/.."

rand() { head -c 16 /dev/urandom | od -An -tx1 | tr -d ' \n'; }

MID="CTF{log_entry_$(rand)}"

cat > .env <<EOF
# generated by flags/init_flags.sh — do not commit
MID_FLAG=${MID}
EOF

echo "wrote .env with a fresh MID_FLAG."
echo "  mid (lab log entry): ${MID}"
